e"":""id"",""type"":""integer"",""default"":""1"",""nullable"":""NO"",""position"":1},{""udt"":""numeric"",""name"":""fixed_prize_amount"",""type"":""numeric"",""default"":""600"",""nullable"":""NO"",""position"":2}],""constraints"":[{""name"":""wheel_config_pkey"",""type"":""PRIMARY KEY"",""column"":""id"",""references_table"":""wheel_config"",""references_column"":""id""},{""name"":""2200_17700_1_not_null"",""type"":""CHECK"",""column"":null,""references_table"":null,""references_column"":null},{""name"":""2200_17700_2_not_null"",""type"":""CHECK"",""column"":null,""references_table"":null,""references_column"":null}]},{""name"":""wheel_spins"",""schema"":""public"",""columns"":[{""udt"":""uuid"",""name"":""id"",""type"":""uuid"",""default"":""gen_random_uuid()"",""nullable"":""NO"",""position"":1},{""udt"":""uuid"",""name"":""user_id"",""type"":""uuid"",""default"":null,""nullable"":""NO"",""position"":2},{""udt"":""numeric"",""name"":""amount_won"",""type"":""numeric"",""default"":null,""nullable"":""NO"",""position"":3},{""udt"":""text"",""name"":""trigger_type"",""type"":""text"",""default"":null,""nullable"":""NO"",""position"":4},{""udt"":""timestamptz"",""name"":""created_at"",""type"":""timestamp with time zone"",""default"":""now()"",""nullable"":""YES"",""position"":5},{""udt"":""bool"",""name"":""is_claimed"",""type"":""boolean"",""default"":""false"",""nullable"":""YES"",""position"":6}],""constraints"":[{""name"":""wheel_spins_pkey"",""type"":""PRIMARY KEY"",""column"":""id"",""references_table"":""wheel_spins"",""references_column"":""id""},{""name"":""wheel_spins_trigger_type_check"",""type"":""CHECK"",""column"":null,""references_table"":""wheel_spins"",""references_column"":""trigger_type""},{""name"":""wheel_spins_user_id_fkey"",""type"":""FOREIGN KEY"",""column"":""user_id"",""references_table"":""profiles"",""references_column"":""id""},{""name"":""2200_17709_1_not_null"",""type"":""CHECK"",""column"":null,""references_table"":null,""references_column"":null},{""name"":""2200_17709_2_not_null"",""type"":""CHECK"",""column"":null,""references_table"":null,""references_column"":null},{""name"":""2200_17709_3_not_null"",""type"":""CHECK"",""column"":null,""references_table"":null,""references_column"":null},{""name"":""2200_17709_4_not_null"",""type"":""CHECK"",""column"":null,""references_table"":null,""references_column"":null}]}],""wheel_functions"":[{""name"":""claim_wheel_spin_atomic"",""arguments"":""p_user_id uuid"",""definition"":""CREATE OR REPLACE FUNCTION public.claim_wheel_spin_atomic(p_user_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE\n  v_spin public.wheel_spins%ROWTYPE;\n  v_wallet public.wallets%ROWTYPE;\n  v_prize numeric;\n  v_new_balance numeric;\nBEGIN\n  IF p_user_id IS NULL THEN\n    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'INVALID_REQUEST';\n  END IF;\n\n  -- SKIP LOCKED prevents parallel requests from claiming the same available spin.\n  SELECT * INTO v_spin\n  FROM public.wheel_spins\n  WHERE user_id = p_user_id\n    AND is_claimed = FALSE\n  ORDER BY created_at ASC\n  LIMIT 1\n  FOR UPDATE SKIP LOCKED;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'NO_AVAILABLE_SPIN';\n  END IF;\n\n  SELECT fixed_prize_amount INTO v_prize\n  FROM public.wheel_config\n  WHERE id = 1;\n  v_prize := COALESCE(v_prize, 600);\n  IF v_prize < 0 THEN\n    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'INVALID_REWARD';\n  END IF;\n\n  SELECT * INTO v_wallet\n  FROM public.wallets\n  WHERE user_id = p_user_id\n  FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'WALLET_NOT_FOUND';\n  END IF;\n\n  UPDATE public.wheel_spins\n  SET is_claimed = TRUE,\n      amount_won = v_prize\n  WHERE id = v_spin.id;\n\n  UPDATE public.wallets\n  SET balance = balance + v_prize,\n      updated_at = transaction_timestamp()\n  WHERE user_id = p_user_id\n  RETURNING balance INTO v_new_balance;\n\n  INSERT INTO public.transactions (\n    user_id,\n    type,\n    amount,\n    status,\n    reference,\n    description\n  ) VALUES (\n    p_user_id,\n    'wheel_win',\n    v_prize,\n    'approved',\n    'WHEEL_' || UPPER(SUBSTRING(v_spin.id::text, 1, 8)),\n    'Lucky Wheel Win'\n  );\n\n  RETURN jsonb_build_object(\n    'success', TRUE,\n    'prize', v_prize,\n    'new_balance', v_new_balance\n  );\nEND;\n$function$\n"",""return_type"":""jsonb""}]}"
